questionResults.sql:
SELECT c.full_name, c.dist_au, c.dist_km, c.dist_ld FROM close_approaches c
WHERE c.approach_date >= date('now') AND c.approach_date < date('now', '+1 year')
ORDER BY c.moid_au ASC LIMIT 1;

